    def gaussian_elimination(matrix):
        rows, cols = len(matrix), len(matrix[0])
        for i in range(rows):
            max_row = i
            for j in range(i + 1, rows):
                if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                    max_row = j
            matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
            factor = matrix[i][i]
            for j in range(cols):
                matrix[i][j] /= factor
            for j in range(rows):
                if i != j:
                    factor = matrix[j][i]
                    for k in range(cols):
                        matrix[j][k] -= factor * matrix[i][k]
        return matrix

    def rank(matrix):
        rows, cols = len(matrix), len(matrix[0])
        rank = 0
        for i in range(min(rows, cols)):
            if matrix[i][i] != 0:
                rank += 1
        return rank

    def generate_parity_circuit(n):
        circuit = []
        for _ in range(2**(n-1)):
            gate = random.choice(['AND', 'OR'])
            inputs = [random.choice([0, 1]) for _ in range(n)]
            circuit.append((gate, inputs))
        return circuit

    def tropicalize_circuit(circuit):
        n = len(circuit[0][1])
        p_adic_matrix = [[0] * (n + 1) for _ in range(n + 1)]
        for gate, inputs in circuit:
            if gate == 'AND':
                for i in range(n):
                    if inputs[i] == 1:
                        p_adic_matrix[0][i+1] += 1
            elif gate == 'OR':
                for i in range(n):
                    if inputs[i] == 0:
                        p_adic_matrix[0][i+1] += 1
        return p_adic_matrix

    def compute_minimal_rank(p_adic_matrix):
        rank_value = rank(gaussian_elimination(p_adic_matrix))
        return rank_value

    n = random.choice([5, 10, 15, 20, 30, 40])
